/*
 * win/seek.c - SEEK
 *
 * Original address: 0x00E19576 (map symbol SEEK, no `$': a WIN
 * module-local routine; it sits in win/ beside WAIT_FOR_CONTROLLER and
 * DISK_INIT, the tree's convention for the WIN driver's local routines)
 * Size: 308 bytes (0x00E19576 .. 0x00E196A9)
 * Generated by: Claude Opus 5.5
 *
 * Position the drive for a request: select its head, then seek its
 * cylinder.  Called by WIN_$DO_IO (0x00E19832), WIN_$FORMAT_TRACK
 * (0x00E196F0) and WIN_$INT (0x00E19CA8); returns the status in D0 (the
 * callers' word result slot is never written).  A5 = WIN_ (0xE2B89C).
 * Frame: (0x8,A6) unit, (0xA,A6) dev_unit, (0xC,A6) req, (0x10,A6) wait
 * flag byte (high byte of its word slot; negative = wait here for the
 * seek, otherwise start it and let WIN_$INT finish).
 *
 * Blocks:
 *   0x00E19590-0x00E195C2  status = 0; cyl = req->cylinder; head =
 *                          req->head; regs = the unit's register block;
 *                          two tries (`moveq #0x1,D6' / dbf 0x00E1969A)
 *   0x00E195C4-0x00E195F0  head differs from the current head (+0x72):
 *                          head register, go 8, WAIT_FOR_CONTROLLER, then
 *                          WIN_$CHECK_DISK_STATUS; any error -> check;
 *                          else current head = head
 *   0x00E195F4-0x00E195FC  cylinder equals the current one (+0x74): done
 *   0x00E195FE-0x00E1961E  cylinder register; wait value = the unit's
 *                          eventcount + 1; the flag byte at +0x76 = ~wait;
 *                          mode 0x0A, go 4
 *   0x00E19624-0x00E1962A  not waiting: return -1 (the seek is under way)
 *   0x00E1962C-0x00E1964E  EC_$WAIT(ecs = {&unit ec, TIME_$CLOCKH, nil},
 *                          vals = {value, TIME_$CLOCKH + 8, 0}); the clock
 *                          firing -> reinit
 *   0x00E19650-0x00E1965C  status = WIN_$CHECK_DISK_STATUS; 0 -> done
 *   0x00E1965E-0x00E19676  check: not ready, unknown drive status or
 *                          equipment check -> reinit; anything else ->
 *                          next try
 *   0x00E19680-0x00E19698  reinit: waiting -> win_$reinit_drive(unit,
 *                          dev_unit) (its status dropped), next try;
 *                          not waiting -> return status_$disk_seek_error
 *   0x00E19678-0x00E1967E  done: current cylinder = cyl; return status
 *   0x00E1969E             tries exhausted: return the last status
 *
 * Quirks reproduced:
 *   - The register block is fetched once, before the retry loop.
 *   - A clock timeout reaches reinit with the status still 0, so two
 *     timeouts return status_$ok without the cylinder being recorded.
 */

#include "win/win_internal.h"

/* `addq.l #0x8,D0' 0x00E19634: the seek wait is 8 clock ticks */
#define WIN_SEEK_TICKS  8
/* `moveq #-0x1,D0' 0x00E19628 */
#define WIN_SEEK_STARTED ((status_$t)-1)

status_$t SEEK(uint16_t unit, uint16_t dev_unit, void *req_ptr, uint8_t flags)
{
    win_$request_t *req = (win_$request_t *)req_ptr;
    status_$t status;                   /* D2 */
    uint16_t cyl;                       /* (-0x10,A6) */
    uint16_t head;                      /* D4 */
    volatile uint8_t *regs;             /* A2 */
    int16_t tries;                      /* D6 */
    uint32_t wait_val;                  /* D7, (-0x8,A6) */

    /* 0x00E19590-0x00E195C2 */
    status = status_$ok;
    cyl = req->cylinder;
    head = req->head;
    regs = WIN_UNIT_REGS(unit);

    for (tries = 1; tries >= 0; tries--) {
        /* 0x00E195C4-0x00E195F0 */
        if (head != (uint16_t)WIN_$DATA.image.cur_head) {
            regs[WIN_REG_HEAD] = (uint8_t)head;
            regs[WIN_REG_GO] = WIN_GO_SELECT_HEAD;
            status = WAIT_FOR_CONTROLLER(unit);
            if (status != status_$ok) {
                goto check;
            }
            status = WIN_$CHECK_DISK_STATUS(unit);
            if (status != status_$ok) {
                goto check;
            }
            WIN_$DATA.image.cur_head = (int16_t)head;
        }

        /* 0x00E195F4-0x00E195FC */
        if (cyl == (uint16_t)WIN_$DATA.image.cur_cyl) {
            goto done;
        }

        /* 0x00E195FE-0x00E1961E */
        *(volatile uint16_t *)(regs + WIN_REG_CYLINDER) = cyl;
        wait_val = WIN_UNIT_EC(unit)->value + 1;
        WIN_DATA_BASE[WIN_FLAG_OFFSET] = (uint8_t)~flags;
        regs[WIN_REG_MODE] = WIN_MODE_SEEK;
        regs[WIN_REG_GO] = WIN_GO_SEEK;

        /* 0x00E19624-0x00E1962A */
        if ((int8_t)flags >= 0) {
            return WIN_SEEK_STARTED;
        }

        /* 0x00E1962C-0x00E1964E */
        if (EC_$WAIT((ec_$wait_ecs_t){{ WIN_UNIT_EC(unit),
                                        (ec_$eventcount_t *)&TIME_$CLOCKH,
                                        NULL }},
                     (ec_$wait_vals_t){{ (int32_t)wait_val,
                                         (int32_t)(TIME_$CLOCKH + WIN_SEEK_TICKS),
                                         0 }}) != 0) {
            goto reinit;
        }

        /* 0x00E19650-0x00E1965C */
        status = WIN_$CHECK_DISK_STATUS(unit);
        if (status == status_$ok) {
            goto done;
        }

    check:
        /* 0x00E1965E-0x00E19676 */
        if (status != status_$disk_not_ready &&
            status != status_$unknown_error_status_from_drive &&
            status != status_$disk_equipment_check) {
            continue;
        }

    reinit:
        /* 0x00E19680-0x00E19698 */
        if ((int8_t)flags >= 0) {
            status = status_$disk_seek_error;
            return status;
        }
        win_$reinit_drive(unit, dev_unit);
    }

    /* 0x00E1969E */
    return status;

done:
    /* 0x00E19678-0x00E1967E */
    WIN_$DATA.image.cur_cyl = (int16_t)cyl;
    return status;
}
